diff --git a/src/api/routes.ts b/src/api/routes.ts
index bafe527..b05143a 100644
--- a/src/api/routes.ts
+++ b/src/api/routes.ts
@@ -1,8 +1,14 @@
-import { findNote, listNotes, saveNote } from '../notes/store.ts'
+import { searchNotes } from '../notes/search.ts'
+import { deleteNote, findNote, listNotes, saveNote } from '../notes/store.ts'

 export function handle(method: string, path: string, body: unknown): { status: number; body: unknown } {
   if (method === 'GET' && path === '/notes') return { status: 200, body: listNotes() }

+  if (method === 'GET' && path.startsWith('/notes/search?q=')) {
+    const query = decodeURIComponent(path.slice('/notes/search?q='.length))
+    return { status: 200, body: searchNotes(query) }
+  }
+
   const match = /^\/notes\/(\w+)$/.exec(path)
   if (method === 'GET' && match) {
     const note = findNote(match[1]!)
@@ -14,5 +20,9 @@ export function handle(method: string, path: string, body: unknown): { status: n
     return { status: 204, body: null }
   }

+  if (method === 'DELETE' && match) {
+    return deleteNote(match[1]!) ? { status: 204, body: null } : { status: 404, body: null }
+  }
+
   return { status: 404, body: null }
 }

diff --git a/src/notes/store.ts b/src/notes/store.ts
