--- a/src/notes/store.ts
+++ b/src/notes/store.ts
@@ -16,5 +16,9 @@ export function findNote(id: string): Note | undefined {
 }

 export function listNotes(): Note[] {
-  return [...notes.values()]
+  return [...notes.values()].sort((left, right) => right.updatedAt - left.updatedAt)
+}
+
+export function deleteNote(id: string): boolean {
+  return notes.delete(id)
 }
